ROOT=[dict(id='C1260',meaning='肉；身体组织',core='sarc-/sarco-：肉与身体组织，也能转为“话语像咬人”的比喻。',image='尖刻的话像带着牙齿；医学名称则保留了组织的字面联系。',intro='希腊 sarx 表示肉，词干 sark-、sarko- 进入不同分支。sarcasm 是说话带刺的比喻；sarcophagus 保存古人对制棺石料的称呼；sarcoma 属于医学分类。几条路线有共同词根，却不能互相替换现代含义。',forms='sarc- 与 sarco- 是常见组合形式；sarcasm、sarcastic 的词形历经借入与派生，不是把肉字直接加一个现代后缀。',branches=[['语言中的刺','sarcasm、sarcastic、sarcastically'],['古代器物名称','sarcophagus'],['医学基本词','sarcoma']],contrasts='sarcasm 常借反话挖苦，但不等于所有 irony。sarcophagus 的“食肉”记录古人的命名解释；sarcoma 的“肉”也不能用来替代现代医学分类。',practice='解释 sarcastically 如何让 “Wonderful” 变成挖苦，并说明 sarcophagus 与 sarcoma 分别在哪条历史支线上。',words=[w for w in family if w in keep],exclude=excluded,sources=['https://www.etymonline.com/word/sarcasm','https://www.etymonline.com/word/sarcophagus','https://www.cancer.gov/publications/dictionaries/cancer-terms/def/sarcoma'])]
